package com.queryx.database.entities;
import jakarta.persistence.*; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="tracking_events") public class TrackingEvent { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="shipment_id",nullable=false) private Shipment shipment; @Column(name="event_type",nullable=false,length=50) private String eventType; private String location; private String description; @Column(name="occurred_at",nullable=false) private OffsetDateTime occurredAt; @Column(name="created_at",nullable=false) private OffsetDateTime createdAt; public UUID getId(){return id;} public Shipment getShipment(){return shipment;} public void setShipment(Shipment v){shipment=v;} }
